SELECT DISTINCT s."description"
FROM "geologists_specimens" gs
JOIN "specimens" s ON gs."specimentype" = s."type";

286:
SELECT DISTINCT d."degree_level"
FROM "degrees" d
WHERE d."job_post" LIKE '%AI Researcher%';

288:
SELECT DISTINCT "certification"
FROM "degrees"
WHERE "job_post" LIKE '%AI Researcher%';

303:
SELECT DISTINCT "officelocation"
FROM "teachers"
WHERE LOWER("subjecttaught") LIKE '%marketing%';

309:
SELECT DISTINCT h."fees", h."taxes"
FROM "house" h
WHERE CAST(h."house_price" AS NUMERIC) = (
    SELECT MAX(CAST("house_price" AS NUMERIC))
    FROM "house"
);

338:
SELECT "h"."fees"
FROM "house" AS "h"
WHERE CAST("h"."house_price" AS NUMERIC) = (
    SELECT MAX(CAST("house_price" AS NUMERIC))
    FROM "house"
);

340:
SELECT "h"."taxes"
FROM "house" "h"
WHERE CAST("h"."house_price" AS NUMERIC(10, 2)) = (
    SELECT MAX(CAST("house_price" AS NUMERIC(10, 2)))
    FROM "house"
);
